// Runnable demo: reproduces SQL pivot via conditional aggregation in memory.
package com.bank.pivot;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class PivotDemo {
    private static final Logger log = Logger.getLogger(PivotDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        TransactionRepository repo = new TransactionRepository();
        ChannelPivotService service = new ChannelPivotService(repo);

        log.info("=== Channel pivot by region (portable conditional aggregation) ===");
        for (PivotRow row : service.pivotByRegion()) {
            log.info(() -> String.format(
                "region=%s  ATM=Rs.%s  UPI=Rs.%s  NET=Rs.%s",
                row.region, row.atmTotal, row.upiTotal, row.netTotal));
        }
    }
}

// ─── Would be in model/Transaction.java ───
class Transaction {
    final String txnId, region, channel; final BigDecimal amount;
    Transaction(String id, String region, String channel, BigDecimal amount) {
        this.txnId = id; this.region = region;
        this.channel = channel; this.amount = amount;
    }
}

// ─── Would be in model/PivotRow.java ───
class PivotRow {
    final String region; final BigDecimal atmTotal, upiTotal, netTotal;
    PivotRow(String region, BigDecimal atm, BigDecimal upi, BigDecimal net) {
        this.region = region; this.atmTotal = atm;
        this.upiTotal = upi; this.netTotal = net;
    }
}

// ─── Would be in repository/TransactionRepository.java ───
class TransactionRepository {
    List<Transaction> findAll() {
        return List.of(
            new Transaction("T1", "North", "ATM",        new BigDecimal("40000")),
            new Transaction("T2", "North", "UPI",        new BigDecimal("15000")),
            new Transaction("T3", "North", "NETBANKING", new BigDecimal("20000")),
            new Transaction("T4", "West",  "UPI",        new BigDecimal("25000")),
            new Transaction("T5", "West",  "ATM",        new BigDecimal("10000")));
    }
}

// ─── Would be in service/ChannelPivotService.java ───
class ChannelPivotService {
    private final TransactionRepository repo;
    ChannelPivotService(TransactionRepository repo) { this.repo = repo; }

    // Mirrors: GROUP BY region, SUM(CASE WHEN channel=... THEN amount ELSE 0 END)
    List<PivotRow> pivotByRegion() {
        // group by region preserving order
        Map<String, BigDecimal> atm = new LinkedHashMap<>();
        Map<String, BigDecimal> upi = new LinkedHashMap<>();
        Map<String, BigDecimal> net = new LinkedHashMap<>();
        Set<String> regions = new LinkedHashSet<>();

        for (Transaction t : repo.findAll()) {
            regions.add(t.region);
            // each branch is one CASE WHEN column
            switch (t.channel) {
                case "ATM"        -> atm.merge(t.region, t.amount, BigDecimal::add);
                case "UPI"        -> upi.merge(t.region, t.amount, BigDecimal::add);
                case "NETBANKING" -> net.merge(t.region, t.amount, BigDecimal::add);
                default -> { /* unknown channel ignored */ }
            }
        }
        List<PivotRow> out = new ArrayList<>();
        for (String r : regions) {
            out.add(new PivotRow(r,
                atm.getOrDefault(r, BigDecimal.ZERO),
                upi.getOrDefault(r, BigDecimal.ZERO),
                net.getOrDefault(r, BigDecimal.ZERO)));
        }
        return out;
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
